<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Masuk — E-Perpustakaan</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;700&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet">
  <style>
  :root{
    --ink:#1a1a2e;--paper:#f5f0e8;--amber:#c8860a;--amber-lt:#f0c040;
    --amber-bg:#fdf3dc;--warm-gray:#e8e0d0;--muted:#7a7060;--border:#d4c9b0;
    --shadow:rgba(26,26,46,.13);--red:#c0392b;--red-bg:#fdecea;
    --green:#1e7e4a;--green-bg:#eaf7ef;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%;font-family:'DM Sans',sans-serif}

  body{
    display:flex;min-height:100vh;background:var(--paper);
  }

  /* ══════════════ LEFT PANEL ══════════════ */
  .left-panel{
    width:420px;flex-shrink:0;background:var(--ink);
    display:flex;flex-direction:column;position:relative;overflow:hidden;
  }

  /* Decorative circles */
  .left-panel::before{
    content:'';position:absolute;width:360px;height:360px;border-radius:50%;
    border:1px solid rgba(200,134,10,.18);
    top:-80px;left:-80px;pointer-events:none;
  }
  .left-panel::after{
    content:'';position:absolute;width:260px;height:260px;border-radius:50%;
    border:1px solid rgba(200,134,10,.10);
    bottom:60px;right:-60px;pointer-events:none;
  }

  /* Amber accent line top */
  .left-panel-line{height:3px;background:linear-gradient(90deg,var(--amber),var(--amber-lt),transparent);width:100%}

  .left-inner{flex:1;display:flex;flex-direction:column;padding:40px 40px 32px;position:relative;z-index:1}

  /* Brand */
  .brand{display:flex;align-items:center;gap:14px;margin-bottom:52px}
  .brand-logo{
    width:56px;height:56px;border-radius:50%;overflow:hidden;flex-shrink:0;
    border:2px solid rgba(200,134,10,.5);
    box-shadow:0 0 0 4px rgba(200,134,10,.10);
  }
  .brand-logo img{width:100%;height:100%;object-fit:cover}
  .brand-text{}
  .brand-name{font-family:'Playfair Display',serif;font-size:17px;font-weight:700;color:#fff;line-height:1.2}
  .brand-sub{font-size:11px;color:rgba(255,255,255,.45);margin-top:3px;font-weight:300;letter-spacing:.03em}

  /* Middle copy */
  .left-copy{flex:1}
  .left-tag{
    display:inline-block;font-size:11px;font-weight:500;text-transform:uppercase;
    letter-spacing:.1em;color:var(--amber);background:rgba(200,134,10,.12);
    padding:4px 12px;border-radius:20px;margin-bottom:20px;border:1px solid rgba(200,134,10,.25);
  }
  .left-copy h1{
    font-family:'Playfair Display',serif;font-size:30px;font-weight:700;
    color:#fff;line-height:1.3;margin-bottom:16px;
  }
  .left-copy h1 em{color:var(--amber-lt);font-style:normal}
  .left-copy p{font-size:14px;color:rgba(255,255,255,.55);font-weight:300;line-height:1.7;margin-bottom:36px}

  /* Features */
  .features{display:flex;flex-direction:column;gap:14px}
  .feat{display:flex;align-items:center;gap:12px}
  .feat-dot{
    width:30px;height:30px;border-radius:8px;background:rgba(200,134,10,.15);
    border:1px solid rgba(200,134,10,.25);display:flex;align-items:center;justify-content:center;flex-shrink:0;
  }
  .feat-dot svg{width:14px;height:14px;color:var(--amber)}
  .feat span{font-size:13px;color:rgba(255,255,255,.7);font-weight:400}

  /* Bottom */
  .left-foot{
    font-size:11.5px;color:rgba(255,255,255,.3);
    padding-top:28px;border-top:1px solid rgba(255,255,255,.07);
    display:flex;align-items:center;justify-content:space-between;
  }
  .left-foot span{color:rgba(200,134,10,.6)}

  /* ══════════════ RIGHT PANEL ══════════════ */
  .right-panel{
    flex:1;display:flex;align-items:center;justify-content:center;
    padding:40px 24px;background:var(--paper);position:relative;
  }

  /* Subtle texture dots */
  .right-panel::before{
    content:'';position:absolute;inset:0;
    background-image:radial-gradient(circle,rgba(26,26,46,.06) 1px,transparent 1px);
    background-size:24px 24px;pointer-events:none;
  }

  .form-box{
    width:100%;max-width:420px;position:relative;z-index:1;
  }

  /* Form header */
  .form-heading{margin-bottom:32px}
  .form-heading h2{
    font-family:'Playfair Display',serif;font-size:26px;font-weight:700;
    color:var(--ink);margin-bottom:6px;
  }
  .form-heading h2 span{color:var(--amber)}
  .form-heading p{font-size:13.5px;color:var(--muted);font-weight:300}

  /* Divider accent */
  .form-heading-bar{
    width:48px;height:3px;background:var(--amber);border-radius:2px;margin-top:14px;
  }

  /* Card */
  .form-card{
    background:#fff;border:1px solid var(--border);border-radius:16px;
    padding:32px;box-shadow:0 4px 30px var(--shadow);
  }

  /* Alerts */
  .alert{
    display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:10px;
    font-size:13.5px;margin-bottom:20px;font-weight:400;
  }
  .alert svg{width:16px;height:16px;flex-shrink:0}
  .alert-success{background:var(--green-bg);color:var(--green);border:1px solid #b6e4c8}
  .alert-danger{background:var(--red-bg);color:var(--red);border:1px solid #f5c0bb}

  /* Form groups */
  .form-group{margin-bottom:20px}
  .form-group label{
    display:block;font-size:12px;font-weight:500;text-transform:uppercase;
    letter-spacing:.07em;color:var(--muted);margin-bottom:8px;
  }
  .input-wrap{
    display:flex;align-items:center;gap:10px;
    background:var(--paper);border:1.5px solid var(--border);border-radius:10px;
    padding:0 14px;transition:border-color .2s,background .2s;
  }
  .input-wrap:focus-within{border-color:var(--amber);background:#fff;box-shadow:0 0 0 3px rgba(200,134,10,.10)}
  .input-wrap.err{border-color:var(--red)}
  .input-wrap svg{width:16px;height:16px;color:var(--muted);flex-shrink:0}
  .input-wrap input{
    flex:1;border:none;outline:none;background:transparent;padding:12px 0;
    font-family:'DM Sans',sans-serif;font-size:14px;color:var(--ink);
  }
  .input-wrap input::placeholder{color:var(--border)}
  .err-text{font-size:12px;color:var(--red);margin-top:5px}

  /* Toggle password */
  .pw-toggle{
    background:none;border:none;cursor:pointer;padding:0;
    display:flex;align-items:center;color:var(--muted);transition:color .2s;
  }
  .pw-toggle:hover{color:var(--amber)}
  .pw-toggle svg{width:16px;height:16px}

  /* Meta row */
  .form-meta{
    display:flex;align-items:center;justify-content:space-between;
    margin-bottom:24px;font-size:13px;
  }
  .check-label{
    display:flex;align-items:center;gap:8px;cursor:pointer;color:var(--ink);
    user-select:none;
  }
  .check-label input[type=checkbox]{
    width:16px;height:16px;accent-color:var(--amber);cursor:pointer;
  }
  .link-forgot{
    color:var(--amber);text-decoration:none;font-weight:500;font-size:13px;
  }
  .link-forgot:hover{text-decoration:underline}

  /* Submit button */
  .btn-masuk{
    width:100%;padding:13px;border:none;border-radius:10px;cursor:pointer;
    font-family:'DM Sans',sans-serif;font-size:14px;font-weight:500;
    background:var(--ink);color:#fff;
    display:flex;align-items:center;justify-content:center;gap:8px;
    transition:background .2s,transform .15s,box-shadow .2s;
    box-shadow:0 4px 16px rgba(26,26,46,.25);
  }
  .btn-masuk:hover{background:var(--amber);color:var(--ink);box-shadow:0 4px 20px rgba(200,134,10,.35);transform:translateY(-1px)}
  .btn-masuk:active{transform:translateY(0)}
  .btn-masuk svg{width:16px;height:16px}

  /* Footer note */
  .foot-note{
    text-align:center;font-size:12px;color:var(--muted);
    margin-top:20px;font-weight:300;
  }

  /* ══════════════ RESPONSIVE ══════════════ */
  @media(max-width:820px){
    .left-panel{display:none}
    .right-panel{background:var(--ink);padding:24px 16px}
    .right-panel::before{background-image:radial-gradient(circle,rgba(200,134,10,.08) 1px,transparent 1px)}
    .form-box{max-width:400px}
  }
  </style>
</head>
